<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { ChatDotRound, Search, Star } from '@element-plus/icons-vue'
import { http } from '@/api/request'
import { imageUrl } from '@/api/upload'

type Category = { id: number; code: string; name: string; icon?: string | null }
type Post = { id: number; title: string; content: string; images?: string[]; location_name?: string | null; created_at: string; is_pinned: boolean; author?: { nickname?: string | null }; category?: Category; like_count: number; favorite_count: number; comment_count: number; is_liked: boolean; is_favorited: boolean }

const router = useRouter()
const loading = ref(false)
const error = ref('')
const categories = ref<Category[]>([])
const posts = ref<Post[]>([])
const filters = reactive({ categoryId: '', keyword: '', sort: 'latest' })
const data = (result: any) => result?.data?.data ?? result?.data ?? result ?? {}
const dateText = (value: string) => { const date = new Date(value); return Number.isNaN(date.getTime()) ? '-' : date.toLocaleString('zh-CN', { month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit', hour12: false }) }
const filtered = computed(() => posts.value.filter(post => !filters.keyword.trim() || `${post.title}${post.content}${post.location_name || ''}`.toLowerCase().includes(filters.keyword.trim().toLowerCase())))

async function load() { loading.value = true; error.value = ''; try { const [categoryResult, postResult] = await Promise.all([http.get('/forum/categories'), http.get('/forum/posts', { params: { page: 1, page_size: 40, category_id: filters.categoryId || undefined, sort: filters.sort } })]); const categoryData = data(categoryResult); const postData = data(postResult); categories.value = Array.isArray(categoryData.list) ? categoryData.list : []; posts.value = Array.isArray(postData.list) ? postData.list : [] } catch (err: any) { error.value = err?.response?.data?.error || err.message || '信息广场加载失败'; ElMessage.error(error.value) } finally { loading.value = false } }
function setCategory(id = '') { filters.categoryId = id; void load() }
function open(id: number) { router.push(`/forum/${id}`) }
function publish() { router.push('/forum/publish') }
async function toggle(post: Post, type: 'like' | 'favorite') { const enabled = type === 'like' ? !post.is_liked : !post.is_favorited; const state = type === 'like' ? 'is_liked' : 'is_favorited'; const count = type === 'like' ? 'like_count' : 'favorite_count'; (post as any)[state] = enabled; (post as any)[count] = Math.max(0, Number((post as any)[count] || 0) + (enabled ? 1 : -1)); try { const response = data(enabled ? await http.post(`/forum/posts/${post.id}/${type}`) : await http.delete(`/forum/posts/${post.id}/${type}`)); (post as any)[count] = Number(response[`${type}_count`] ?? (post as any)[count]) } catch (err: any) { (post as any)[state] = !enabled; (post as any)[count] = Math.max(0, Number((post as any)[count] || 0) + (enabled ? -1 : 1)); ElMessage.error(err?.response?.data?.error || err.message || '操作失败') } }

onMounted(load)
</script>

<template>
  <section class="square" v-loading="loading">
    <header class="square-head"><p>失物招领、二手交易、表白墙与校园通知，都在这里发生。</p><el-button type="primary" @click="publish">发布信息</el-button></header>
    <section class="filter-panel"><div class="category-list"><button class="category-chip" :class="{ active: !filters.categoryId }" type="button" @click="setCategory()">全部</button><button v-for="category in categories" :key="category.id" class="category-chip" :class="{ active: filters.categoryId === String(category.id) }" type="button" @click="setCategory(String(category.id))">{{ category.name }}</button></div><div class="filter-row"><el-input v-model="filters.keyword" clearable :prefix-icon="Search" placeholder="搜索物品、地点或关键词" /><el-radio-group v-model="filters.sort" @change="load"><el-radio-button label="latest">最新</el-radio-button><el-radio-button label="hot">热门</el-radio-button></el-radio-group></div></section>
    <div v-if="error" class="square-error" role="alert"><span>{{ error }}</span><el-button type="primary" plain @click="load">重新加载</el-button></div>
    <el-empty v-else-if="!loading && !filtered.length" description="暂时没有相关校园信息"><el-button type="primary" @click="publish">发布第一条</el-button></el-empty>
    <main v-else class="post-list"><article v-for="post in filtered" :key="post.id" class="post" tabindex="0" @click="open(post.id)" @keyup.enter="open(post.id)"><div class="post-header"><div class="author"><div class="avatar">{{ (post.author?.nickname || '同').slice(0, 1) }}</div><div><strong>{{ post.author?.nickname || '校园同学' }}</strong><span>{{ dateText(post.created_at) }}{{ post.location_name ? ` · ${post.location_name}` : '' }}</span></div></div><el-tag v-if="post.is_pinned" type="primary" effect="plain">置顶</el-tag></div><el-tag effect="plain" class="category">{{ post.category?.name || '校园信息' }}</el-tag><h3>{{ post.title }}</h3><p>{{ post.content }}</p><div v-if="post.images?.length" class="images"><img v-for="image in post.images.slice(0, 3)" :key="image" :src="imageUrl(image)" alt="帖子图片" /></div><footer @click.stop><button :class="{ active: post.is_liked }" type="button" @click="toggle(post, 'like')">♥ {{ post.like_count }}</button><button type="button" @click="open(post.id)"><el-icon><ChatDotRound /></el-icon> {{ post.comment_count }}</button><button :class="{ active: post.is_favorited }" type="button" @click="toggle(post, 'favorite')"><el-icon><Star /></el-icon> {{ post.favorite_count }}</button><button class="detail" type="button" @click="open(post.id)">查看详情 →</button></footer></article></main>
  </section>
</template>

<style scoped>
.square { display: grid; gap: 20px; }.square-head { display: flex; align-items: end; justify-content: space-between; gap: 24px; border-bottom: 1px solid var(--color-border); padding: 8px 0 20px; }.square-head p { margin: 0; color: var(--color-text-muted); }.filter-panel { display: grid; gap: 14px; border: 1px solid var(--color-border); border-radius: var(--radius-card); padding: 16px; background: var(--color-surface); }.category-list { display: flex; flex-wrap: wrap; gap: 8px; }.category-chip { border: 1px solid var(--color-border); border-radius: var(--radius-pill); padding: 6px 11px; background: var(--color-surface); color: var(--color-text-secondary); font-size: 13px; font-weight: 700; transition: border-color var(--transition-fast), background var(--transition-fast), color var(--transition-fast); }.category-chip:hover { border-color: var(--color-primary); color: var(--color-primary); }.category-chip.active { border-color: var(--color-primary); background: var(--color-primary); color: #fff; }.filter-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; }.filter-row :deep(.el-input) { max-width: 360px; }.post-list { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }.post { display: grid; gap: 12px; min-width: 0; border: 1px solid var(--color-border); border-radius: var(--radius-card); padding: 20px; background: var(--color-surface); cursor: pointer; transition: border-color var(--transition-fast), transform var(--transition-fast); }.post:hover, .post:focus-visible { border-color: var(--color-primary); outline: 0; transform: translateY(-1px); }.post-header, .author, footer { display: flex; align-items: center; }.post-header { justify-content: space-between; gap: 12px; }.author { min-width: 0; gap: 9px; }.avatar { display: grid; width: 36px; height: 36px; flex: 0 0 36px; place-items: center; border-radius: 50%; background: var(--color-primary-soft); color: var(--color-primary-active); font-size: 14px; font-weight: 800; }.author strong, .author span { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.author strong { color: var(--color-navy); font-size: 13px; }.author span { margin-top: 2px; color: var(--color-text-muted); font-size: 11px; }.category { justify-self: start; }.post h3 { overflow: hidden; margin: 0; color: var(--color-navy); text-overflow: ellipsis; white-space: nowrap; font-size: 18px; }.post > p { display: -webkit-box; overflow: hidden; margin: 0; color: var(--color-text-secondary); line-height: 1.65; -webkit-box-orient: vertical; -webkit-line-clamp: 3; }.images { display: grid; grid-template-columns: repeat(3, 1fr); gap: 7px; }.images img { width: 100%; height: 112px; border-radius: 8px; object-fit: cover; } footer { gap: 14px; color: var(--color-text-muted); font-size: 12px; } footer button { display: inline-flex; align-items: center; gap: 4px; border: 0; padding: 0; background: none; color: inherit; cursor: pointer; } footer button:hover, footer button.active { color: var(--color-primary); font-weight: 800; }.detail { margin-left: auto; color: var(--color-primary); }.square-error { display: flex; align-items: center; justify-content: space-between; gap: 14px; border: 1px solid var(--color-border-strong); border-radius: var(--radius-card); padding: 14px 16px; background: var(--color-fill); color: var(--color-text-secondary); } @media (max-width: 760px) { .square-head { align-items: flex-start; flex-direction: column; }.filter-row { align-items: stretch; flex-direction: column; }.filter-row :deep(.el-input) { max-width: none; }.post-list { grid-template-columns: 1fr; } } @media (max-width: 460px) { footer { gap: 10px; }.detail { display: none; } }
</style>
